mapper.sql:
p.insp_type = #{k.inspType}
and coalesce(p.item_id, 0) = coalesce(cast(#{k.itemId} as bigint), 0)
and coalesce(p.item_class_id, 0) = coalesce(cast(#{k.itemClassId} as bigint), 0)
and coalesce(p.proc_id, 0) = coalesce(cast(#{k.procId} as bigint), 0)
and p.alt_no = #{k.altNo}

mapper.update:
update qms_insp_plan
   set rev = #{f.rev}, valid_from = #{f.validFrom}, change_no = #{f.changeNo}, change_reason = #{f.changeReason},
       remark = #{f.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where insp_plan_id = #{id} and status = 'DRAFT' and row_ver = #{f.rowVer}

update qms_insp_plan set status = 'RELEASED', released_at = now(), released_by = #{by},
                         row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where insp_plan_id = #{id} and status = 'DRAFT' and row_ver = #{rowVer}

update qms_insp_plan_line
   set line_no = #{l.lineNo}, char_id = #{l.charId}, method_nm = #{l.methodNm}, gauge_class = #{l.gaugeClass},
       sampling_plan_id = #{l.samplingPlanId}, freq_type = #{l.freqType}, freq_n = #{l.freqN},
       reaction_plan = #{l.reactionPlan}, remark = #{l.remark}, grp_nm = #{l.grpNm}, evidence_req = #{l.evidenceReq},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where line_id = #{l.lineId} and insp_plan_id = #{planId}

mapper.insert:
insert into qms_insp_plan_line (comp_cd, insp_plan_id, line_no, char_id, method_nm, gauge_class, sampling_plan_id, freq_type,
                                freq_n, reaction_plan, remark, grp_nm, evidence_req, created_by, updated_by)
select comp_cd, #{toId}, line_no, char_id, method_nm, gauge_class, sampling_plan_id, freq_type, freq_n, reaction_plan, remark,
       grp_nm, evidence_req, #{by}, #{by}
  from qms_insp_plan_line where insp_plan_id = #{fromId}
 order by line_no
